(()=>{
'use strict';
const isJournal=item=>item.kind==='journal'||/^USRCMD_/i.test(item.id)||item.id==='NX_SHORTCUT_STUDIO_TOGGLE_REFERENCE_GEOMETRY';
function validateId(id){return typeof id==='string'&&/^[A-Za-z0-9_.:-]{1,128}$/.test(id)&&id!=='NX_SHORTCUT_STUDIO_TOGGLE_REFERENCE_GEOMETRY'}
function configure(item,list,label,id){label=label.trim();id=id.trim();if(!label||label.length>=100)throw Error('Use a command name between 1 and 99 characters.');if(!validateId(id))throw Error('Paste the actual NX button command ID, not the old placeholder.');if(list.some(other=>other!==item&&other.id===id))throw Error('That command ID is already assigned in this workspace.');item.label=label;item.id=id;item.kind='journal';item.type='button';return item}
function decorate(name,item,list,onSave,onEdit){if(!isJournal(item))return;const details=document.createElement('details');details.className='journal-binding-editor';const summary=document.createElement('summary');summary.textContent='Edit journal name / command ID';details.append(summary);const form=document.createElement('form');const labelInput=document.createElement('input');labelInput.value=item.label;labelInput.setAttribute('aria-label','Journal command name');const idInput=document.createElement('input');idInput.value=item.id;idInput.spellcheck=false;idInput.setAttribute('aria-label','NX journal button command ID');const button=document.createElement('button');button.type='submit';button.textContent='Save journal command';form.append(labelInput,idInput,button);details.append(form);details.addEventListener('toggle',()=>{if(details.open)onEdit()});form.onsubmit=event=>{event.preventDefault();try{configure(item,list,labelInput.value,idInput.value);onSave()}catch(error){alert(error.message)}};name.append(details)}
window.NX_JOURNAL_COMMANDS={isJournal,validateId,configure,decorate};
const setup=document.querySelector('.journal-setup');setup.replaceChildren();
const nameLabel=document.createElement('label');nameLabel.textContent='Journal command name';const nameInput=document.createElement('input');nameInput.id='journalCommandName';nameInput.value='Toggle Create Reference Geometry';nameLabel.append(nameInput);
const idLabel=document.createElement('label');idLabel.textContent='NX button command ID';const idInput=document.createElement('input');idInput.id='journalCommandId';idInput.placeholder='Paste your own NX custom button ID';idInput.spellcheck=false;idLabel.append(idInput);
const scopeLabel=document.createElement('label');scopeLabel.textContent='Keyboard workspace';const scope=document.createElement('select');scope.id='journalCommandScope';for(const [value,label] of [['sketch','Sketching'],['modeling','Modeling / general']]){const option=document.createElement('option');option.value=value;option.textContent=label;scope.append(option)}scopeLabel.append(scope);
const button=document.createElement('button');button.id='addJournalCommandBtn';button.className='primary';button.textContent='Add / update journal command';button.onclick=()=>{const label=nameInput.value.trim(),id=idInput.value.trim();if(!validateId(id)||!label||label.length>=100){alert('Enter a command name and the actual NX button ID shown in Customize.');return}document.dispatchEvent(new CustomEvent('nx:add-journal-command',{detail:{id,label,scope:scope.value}}))};setup.append(nameLabel,idLabel,scopeLabel,button);
document.querySelector('.journal-panel h2').textContent='Journal commands on your keyboard';
document.querySelector('.journal-panel .section-title p').textContent='Name a journal command, paste its NX button ID, then record a shortcut. The downloadable reference-geometry journal is one example.';
document.querySelector('.journal-panel .journal-note').textContent='Use your own NX command ID. Export uses that exact ID; it does not embed or install the journal button. Keep the custom button and its journal file installed in NX.';
})();
